SELECT product_id, CASE WHEN YEAR(last_restock) < 2024 THEN 'before_2024' WHEN YEAR(last_restock) = 2024 THEN '2024' ELSE 'after_2024' END AS last_restock_cohort, SUM(quantity) AS total_quantity, MIN(quantity) AS min_quantity, ROUND(AVG(quantity), 2) AS avg_quantity FROM inventory WHERE last_restock < '2024-01-21' AND product_id IN (4, 7, 10) GROUP BY product_id, CASE WHEN YEAR(last_restock) < 2024 THEN 'before_2024' WHEN YEAR(last_restock) = 2024 THEN '2024' ELSE 'after_2024' END HAVING COUNT(quantity) > 1
